import React, { useEffect, useState } from 'react'
import {
  Activity, AlarmClock, Apple, ArrowLeft, BarChart3, Bell, CalendarDays,
  Check, CheckCircle2, ChevronRight, ClipboardCheck, Clock3, Download, Droplets,
  FileHeart, FileText, FlaskConical, Goal, HeartPulse, Home, ImagePlus, LayoutDashboard,
  Leaf, LogOut, Mail, Menu, MessageCircle, MoreHorizontal, NotebookTabs, PackagePlus,
  PanelLeftClose, Plus, Receipt, Scale, Search, Send, Settings, ShieldCheck, Sparkles,
  Stethoscope, Target, Trash2, UserRound, UsersRound, Utensils, WalletCards, X, Zap
} from 'lucide-react'
import { loadData, patientName, saveData, SESSION_KEY, uid } from './data'

const money = value => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value || 0)
const dateBR = value => value ? new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).format(new Date(`${value}`.length===10?`${value}T12:00:00`:value)) : '—'
const timeBR = value => value ? new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(new Date(value)) : '—'
const clamp = n => Math.max(0,Math.min(100,Number(n)||0))
const calcBMI = (weight,height) => height ? (weight/((height/100)**2)).toFixed(1) : '—'
const firstName = name => (name || '').split(' ')[0]

function BrandMark({size=34}){
  return <svg width={size} height={size} viewBox="0 0 40 40" fill="none" aria-hidden="true">
    <rect width="40" height="40" rx="11" fill="currentColor" opacity=".12"/>
    <path d="M11.5 26.5c3.4-8.7 7.7-13 13-13 2.6 0 4.6.8 6 2.3-5.4.2-9.8 2-13.1 5.3-2 2.1-3.4 4.2-4.2 6.4-.4 1.1-2.1.1-1.7-1Z" fill="currentColor"/>
    <path d="M16 29c1.3-6 5.1-10.2 11.4-12.6-1.4 6.8-5.2 11-11.4 12.6Z" fill="currentColor" opacity=".55"/>
  </svg>
}
function Brand({compact=false}){ return <div className="brand"><span className="brandSymbol"><BrandMark size={compact?31:36}/></span>{!compact&&<div className="brandType"><strong>my nutri</strong><span>clinical workspace</span></div>}</div> }
function Badge({children,tone='neutral'}){ return <span className={`badge ${tone}`}>{children}</span> }
function Button({children,variant='primary',className='',...props}){ return <button className={`btn ${variant} ${className}`} {...props}>{children}</button> }
function SectionTitle({title,description,action}){ return <div className="sectionTitle"><div><h2>{title}</h2>{description&&<p>{description}</p>}</div>{action}</div> }
function Empty({icon:Icon=NotebookTabs,title='Nada por aqui',text='Adicione o primeiro registro para começar.'}){ return <div className="emptyState"><span><Icon size={24}/></span><strong>{title}</strong><p>{text}</p></div> }
function ProgressBar({value}){ return <div className="progressTrack"><span style={{width:`${clamp(value)}%`}}/></div> }
function Field({label,children,hint}){ return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label> }
function Stat({label,value,meta,icon:Icon,tone='default'}){ return <div className={`stat ${tone}`}>{Icon&&<span className="statIcon"><Icon size={18}/></span>}<div><small>{label}</small><strong>{value}</strong>{meta&&<span>{meta}</span>}</div></div> }
function Modal({title,subtitle,onClose,children,size='md'}){ return <div className="modalBackdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className={`modal ${size}`}><div className="modalHead"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><button className="iconBtn" onClick={onClose}><X size={19}/></button></div>{children}</div></div> }

function Login({onLogin}){
  const [role,setRole]=useState('nutritionist'); const [email,setEmail]=useState('nutri@mynutri.app')
  const submit=e=>{e.preventDefault();onLogin({role,email:email.trim()})}
  return <div className="loginLayout"><section className="loginEditorial"><Brand/><div className="loginCopy"><Badge tone="purple"><ShieldCheck size={13}/> ambiente demonstrativo</Badge><h1>Nutrição clínica organizada como um produto profissional.</h1><p>Atendimento, prontuário, prescrição, acompanhamento e relacionamento em um único fluxo.</p></div><div className="loginFeatureGrid"><div><Stethoscope/><span><b>Consulta completa</b><small>Anamnese, antropometria e exames</small></span></div><div><Utensils/><span><b>Prescrição precisa</b><small>Plano alimentar e metas</small></span></div><div><MessageCircle/><span><b>Acompanhamento</b><small>Diário, chat e evolução</small></span></div><div><BarChart3/><span><b>Gestão do consultório</b><small>Agenda, financeiro e relatórios</small></span></div></div><small className="loginLegal">my nutri · produto independente para gestão nutricional</small></section><section className="loginPanel"><form className="authCard" onSubmit={submit}><div className="mobileBrand"><Brand/></div><div className="authTitle"><span>Acesso seguro</span><h2>Entrar no my nutri</h2><p>Escolha o ambiente que deseja visualizar.</p></div><div className="segmented"><button type="button" className={role==='nutritionist'?'active':''} onClick={()=>{setRole('nutritionist');setEmail('nutri@mynutri.app')}}><Stethoscope size={17}/> Nutricionista</button><button type="button" className={role==='patient'?'active':''} onClick={()=>{setRole('patient');setEmail('lucas@mynutri.app')}}><UserRound size={17}/> Paciente</button></div><Field label="E-mail"><input type="email" value={email} onChange={e=>setEmail(e.target.value)} required/></Field><Field label="Senha"><input type="password" defaultValue="123456" required/></Field><div className="authAux"><label><input type="checkbox" defaultChecked/> Manter conectado</label><button type="button">Esqueci a senha</button></div><Button type="submit" className="full">Acessar workspace <ChevronRight size={17}/></Button><div className="demoNote"><ShieldCheck size={16}/><span>Modo demonstração: dados ficam apenas neste navegador até a conexão com Supabase ser configurada.</span></div></form></section></div>
}

const proNav=[
  {section:'Atendimento',items:[['dashboard',LayoutDashboard,'Visão geral'],['patients',UsersRound,'Pacientes'],['agenda',CalendarDays,'Agenda'],['messages',MessageCircle,'Mensagens']]},
  {section:'Prescrição',items:[['plans',Utensils,'Planos e modelos'],['foods',Apple,'Alimentos e receitas']]},
  {section:'Consultório',items:[['finance',WalletCards,'Financeiro'],['reports',BarChart3,'Relatórios'],['settings',Settings,'Configurações']]},
]
const patientNav=[
  {section:'Minha jornada',items:[['today',Home,'Hoje'],['myplan',Utensils,'Plano alimentar'],['diary',NotebookTabs,'Diário'],['progress',Activity,'Evolução'],['goals',Goal,'Metas']]},
  {section:'Contato',items:[['messages',MessageCircle,'Mensagens'],['documents',FileText,'Documentos'],['profile',UserRound,'Meu perfil']]},
]
function Sidebar({role,page,setPage,logout,collapsed,setCollapsed}){
  const groups=role==='nutritionist'?proNav:patientNav
  return <aside className={`sidebar ${collapsed?'collapsed':''}`}><div className="sideTop"><Brand compact={collapsed}/><button className="collapseBtn" onClick={()=>setCollapsed(!collapsed)}><PanelLeftClose size={18}/></button></div><nav>{groups.map(group=><div className="navGroup" key={group.section}>{!collapsed&&<span className="navLabel">{group.section}</span>}{group.items.map(([id,Icon,label])=><button key={id} title={collapsed?label:undefined} className={page===id?'active':''} onClick={()=>setPage(id)}><Icon size={18}/>{!collapsed&&<span>{label}</span>}</button>)}</div>)}</nav><div className="sideFooter"><button className="profileMini"><span className="avatar small">{role==='nutritionist'?'MS':'LA'}</span>{!collapsed&&<span><b>{role==='nutritionist'?'Mariana Silva':'Lucas Andrade'}</b><small>{role==='nutritionist'?'Nutricionista':'Paciente'}</small></span>}</button><button className="logoutBtn" onClick={logout} title="Sair"><LogOut size={18}/>{!collapsed&&'Sair'}</button></div></aside>
}
function Topbar({role,page,mobileOpen,setMobileOpen}){
  const titles={dashboard:'Visão geral',patients:'Pacientes',agenda:'Agenda',messages:'Mensagens',plans:'Planos e modelos',foods:'Alimentos e receitas',finance:'Financeiro',reports:'Relatórios',settings:'Configurações',today:'Hoje',myplan:'Plano alimentar',diary:'Diário alimentar',progress:'Evolução',goals:'Metas',documents:'Documentos',profile:'Meu perfil'}
  return <header className="topbar"><button className="mobileMenu" onClick={()=>setMobileOpen(!mobileOpen)}><Menu size={20}/></button><div className="topCrumb"><span>{role==='nutritionist'?'Workspace clínico':'Área do paciente'}</span><ChevronRight size={14}/><strong>{titles[page]||'my nutri'}</strong></div><div className="topActions"><button className="globalSearch"><Search size={17}/><span>Buscar</span><kbd>⌘ K</kbd></button><button className="iconBtn notification"><Bell size={18}/><i/></button><span className="avatar">{role==='nutritionist'?'MS':'LA'}</span></div></header>
}

function Dashboard({data,setPage,setSelectedPatient}){
  const pending=data.finance.filter(x=>x.status==='pending').reduce((a,x)=>a+x.amount,0); const active=data.patients.filter(p=>p.status==='active'); const next=data.appointments.filter(a=>a.status==='scheduled').sort((a,b)=>a.startsAt.localeCompare(b.startsAt)).slice(0,4); const attention=active.filter(p=>p.risk==='attention'||p.adherence<80)
  return <div className="page"><div className="pageIntro"><div><span className="kicker">Operação clínica · 27 ago 2026</span><h1>Visão geral</h1><p>O que precisa da sua atenção hoje, sem ruído.</p></div><div className="pageActions"><Button variant="secondary" onClick={()=>setPage('agenda')}><CalendarDays size={17}/> Agendar</Button><Button onClick={()=>setPage('patients')}><Plus size={17}/> Novo paciente</Button></div></div><section className="statStrip"><Stat icon={UsersRound} label="Pacientes ativos" value={active.length} meta="+1 neste mês"/><Stat icon={CalendarDays} label="Próximos 7 dias" value={data.appointments.filter(a=>a.status==='scheduled').length} meta="consultas agendadas"/><Stat icon={Target} label="Adesão média" value={`${Math.round(active.reduce((a,p)=>a+p.adherence,0)/Math.max(active.length,1))}%`} meta="últimos registros"/><Stat icon={WalletCards} label="A receber" value={money(pending)} meta="lançamentos abertos"/></section><div className="dashboardColumns"><section className="surface"><SectionTitle title="Agenda de hoje e próximos atendimentos" description="Linha do tempo clínica" action={<Button variant="ghost" onClick={()=>setPage('agenda')}>Abrir agenda <ChevronRight size={16}/></Button>}/><div className="timeline">{next.map(a=><button className="timelineItem" key={a.id} onClick={()=>{setSelectedPatient(a.patientId);setPage('patients')}}><div className="timeBlock"><strong>{timeBR(a.startsAt)}</strong><span>{new Date(a.startsAt).toLocaleDateString('pt-BR',{day:'2-digit',month:'short'})}</span></div><div className="timelineDot"/><div className="timelineBody"><div><strong>{patientName(data,a.patientId)}</strong><Badge tone={a.mode==='Online'?'blue':'neutral'}>{a.mode}</Badge></div><p>{a.type} · {a.duration} min</p></div><ChevronRight size={17}/></button>)}</div></section><section className="surface"><SectionTitle title="Atenção clínica" description="Sinais que merecem revisão"/><div className="attentionList">{attention.length?attention.map(p=><button key={p.id} onClick={()=>{setSelectedPatient(p.id);setPage('patients')}}><span className="avatar">{p.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><span><strong>{p.name}</strong><small>{p.adherence}% de adesão · {p.goal}</small></span><Badge tone="amber">revisar</Badge></button>):<Empty icon={CheckCircle2} title="Tudo em ordem" text="Nenhum alerta clínico no momento."/>}</div></section></div><div className="dashboardColumns lower"><section className="surface"><SectionTitle title="Carteira em acompanhamento" description="Adesão e evolução dos pacientes"/><div className="dataTable"><div className="tableHead"><span>Paciente</span><span>Objetivo</span><span>Adesão</span><span>Última consulta</span><span></span></div>{active.map(p=><button className="tableRow" key={p.id} onClick={()=>{setSelectedPatient(p.id);setPage('patients')}}><span className="personCell"><span className="avatar small">{p.name.slice(0,2).toUpperCase()}</span><span><b>{p.name}</b><small>{p.tags.join(' · ')}</small></span></span><span>{p.goal}</span><span className="adherenceCell"><b>{p.adherence}%</b><ProgressBar value={p.adherence}/></span><span>{dateBR(p.lastAppointment)}</span><ChevronRight size={16}/></button>)}</div></section><section className="surface quickPanel"><SectionTitle title="Atalhos" description="Ações frequentes"/><div className="quickGrid"><button onClick={()=>setPage('patients')}><ClipboardCheck/><span><b>Nova anamnese</b><small>Abrir prontuário</small></span></button><button onClick={()=>setPage('plans')}><Utensils/><span><b>Novo plano</b><small>Usar modelo</small></span></button><button onClick={()=>setPage('finance')}><Receipt/><span><b>Novo lançamento</b><small>Financeiro</small></span></button><button onClick={()=>setPage('reports')}><FileHeart/><span><b>Relatório</b><small>Evolução clínica</small></span></button></div></section></div></div>
}

function PatientList({data,onOpen,onAdd}){
  const [query,setQuery]=useState(''); const [status,setStatus]=useState('all'); const rows=data.patients.filter(p=>(status==='all'||p.status===status)&&(`${p.name} ${p.email} ${p.goal}`).toLowerCase().includes(query.toLowerCase()))
  return <div className="page"><div className="pageIntro"><div><span className="kicker">Gestão clínica</span><h1>Pacientes</h1><p>Prontuário longitudinal, prescrição e acompanhamento em um só lugar.</p></div><Button onClick={onAdd}><Plus size={17}/> Cadastrar paciente</Button></div><section className="surface"><div className="toolbar"><div className="searchBox"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar por nome, e-mail ou objetivo"/></div><select value={status} onChange={e=>setStatus(e.target.value)}><option value="all">Todos os status</option><option value="active">Ativos</option><option value="paused">Pausados</option></select><span className="resultCount">{rows.length} pacientes</span></div><div className="patientTable"><div className="patientTableHead"><span>Paciente</span><span>Objetivo</span><span>Status</span><span>Adesão</span><span>Próxima consulta</span><span></span></div>{rows.map(p=><button className="patientTableRow" key={p.id} onClick={()=>onOpen(p.id)}><span className="personCell"><span className="avatar">{p.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><span><b>{p.name}</b><small>{p.email}</small></span></span><span><b className="cellTitle">{p.goal}</b><small>{p.tags.join(' · ')}</small></span><span><Badge tone={p.status==='active'?'green':'neutral'}>{p.status==='active'?'Ativo':'Pausado'}</Badge></span><span className="adherenceCell"><b>{p.adherence}%</b><ProgressBar value={p.adherence}/></span><span><b className="cellTitle">{dateBR(p.nextAppointment)}</b><small>{timeBR(p.nextAppointment)}</small></span><ChevronRight size={17}/></button>)}</div></section></div>
}
function AddPatientModal({data,setData,onClose,onCreated}){
  const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const birth=f.get('birthDate');const age=birth?Math.floor((Date.now()-new Date(`${birth}T12:00:00`))/(365.25*86400000)):0;const p={id:uid('p'),professionalId:data.professional.id,name:f.get('name'),email:f.get('email'),phone:f.get('phone'),birthDate:birth,age,sex:f.get('sex'),goal:f.get('goal'),weight:Number(f.get('weight')||0),targetWeight:Number(f.get('targetWeight')||0),height:Number(f.get('height')||0),status:'active',tags:['Novo paciente'],nextAppointment:null,lastAppointment:null,adherence:0,risk:'new'};setData(d=>({...d,patients:[p,...d.patients],anamneses:{...d.anamneses,[p.id]:{}},anthropometry:{...d.anthropometry,[p.id]:[]},labs:{...d.labs,[p.id]:[]},mealPlans:{...d.mealPlans,[p.id]:null},goals:{...d.goals,[p.id]:[]},diary:{...d.diary,[p.id]:[]},progress:{...d.progress,[p.id]:[]},notes:{...d.notes,[p.id]:[]},documents:{...d.documents,[p.id]:[]},prescriptions:{...d.prescriptions,[p.id]:[]},messages:{...d.messages,[p.id]:[]}}));onCreated(p.id)}
  return <Modal title="Cadastrar paciente" subtitle="Dados essenciais para iniciar o prontuário." onClose={onClose} size="lg"><form onSubmit={submit}><div className="formGrid cols2"><Field label="Nome completo"><input name="name" required autoFocus/></Field><Field label="E-mail"><input name="email" type="email" required/></Field><Field label="Telefone"><input name="phone" placeholder="(31) 99999-9999"/></Field><Field label="Data de nascimento"><input name="birthDate" type="date"/></Field><Field label="Sexo biológico"><select name="sex"><option value="female">Feminino</option><option value="male">Masculino</option></select></Field><Field label="Objetivo principal"><select name="goal"><option>Emagrecimento</option><option>Recomposição corporal</option><option>Hipertrofia</option><option>Saúde intestinal</option><option>Reeducação alimentar</option><option>Performance esportiva</option><option>Gestação</option></select></Field><Field label="Altura (cm)"><input name="height" type="number" min="80" max="230"/></Field><Field label="Peso atual (kg)"><input name="weight" type="number" step="0.1"/></Field><Field label="Meta de peso (kg)"><input name="targetWeight" type="number" step="0.1"/></Field></div><div className="modalActions"><Button type="button" variant="ghost" onClick={onClose}>Cancelar</Button><Button type="submit"><Plus size={16}/> Criar prontuário</Button></div></form></Modal>
}

const patientTabs=[['overview','Visão clínica'],['anamnesis','Anamnese'],['anthro','Antropometria'],['labs','Exames'],['plan','Plano alimentar'],['goals','Metas'],['diary','Diário'],['docs','Documentos'],['record','Prontuário']]
function PatientWorkspace({data,setData,patientId,onBack}){
  const patient=data.patients.find(p=>p.id===patientId); const [tab,setTab]=useState('overview'); if(!patient) return null
  return <div className="page patientWorkspace"><button className="backLink" onClick={onBack}><ArrowLeft size={16}/> Todos os pacientes</button><section className="patientHeader"><div className="patientIdentity"><span className="avatar xl">{patient.name.split(' ').map(n=>n[0]).slice(0,2).join('')}</span><div><div className="patientNameLine"><h1>{patient.name}</h1><Badge tone="green">Ativo</Badge></div><p>{patient.age} anos · {patient.height} cm · {patient.goal}</p><div className="patientContact"><span><Mail size={14}/>{patient.email}</span><span><CalendarDays size={14}/> próxima: {dateBR(patient.nextAppointment)} · {timeBR(patient.nextAppointment)}</span></div></div></div><div className="patientHeaderStats"><div><small>Peso</small><strong>{patient.weight} kg</strong></div><div><small>IMC</small><strong>{calcBMI(patient.weight,patient.height)}</strong></div><div><small>Adesão</small><strong>{patient.adherence}%</strong></div><button className="iconBtn"><MoreHorizontal size={19}/></button></div></section><div className="tabBar">{patientTabs.map(([id,label])=><button key={id} className={tab===id?'active':''} onClick={()=>setTab(id)}>{label}</button>)}</div><div className="workspaceBody">{tab==='overview'&&<ClinicalOverview patient={patient} data={data} setTab={setTab}/>} {tab==='anamnesis'&&<Anamnesis patient={patient} data={data} setData={setData}/>} {tab==='anthro'&&<Anthropometry patient={patient} data={data} setData={setData}/>} {tab==='labs'&&<Labs patient={patient} data={data} setData={setData}/>} {tab==='plan'&&<MealPlanEditor patient={patient} data={data} setData={setData}/>} {tab==='goals'&&<GoalsModule patient={patient} data={data} setData={setData} professional/>} {tab==='diary'&&<DiaryModule patient={patient} data={data} setData={setData} professional/>} {tab==='docs'&&<DocumentsModule patient={patient} data={data} setData={setData} professional/>} {tab==='record'&&<RecordModule patient={patient} data={data} setData={setData}/>}</div></div>
}
function ClinicalOverview({patient,data,setTab}){
  const anthro=data.anthropometry[patient.id]||[]; const latest=anthro[0]; const labs=data.labs[patient.id]||[]; const alerts=labs.filter(l=>l.status==='attention'); const plan=data.mealPlans[patient.id]; const qs=data.questionnaires[patient.id]||[]; const goals=data.goals[patient.id]||[]; const sexFactor=patient.sex==='male'?5:-161; const bmr=Math.round(10*patient.weight+6.25*patient.height-5*patient.age+sexFactor); const tdee=Math.round(bmr*1.55)
  return <><div className="overviewGrid"><section className="surface"><SectionTitle title="Resumo clínico" description="Indicadores centrais do acompanhamento"/><div className="clinicalMetrics"><Stat label="Peso atual" value={`${patient.weight} kg`} meta={`meta ${patient.targetWeight} kg`} icon={Scale}/><Stat label="Gordura corporal" value={latest?`${latest.bodyFat}%`:'—'} meta={latest?.method||'sem avaliação'} icon={Activity}/><Stat label="Gasto estimado" value={`${tdee} kcal`} meta={`basal ${bmr} kcal`} icon={Zap}/><Stat label="Plano atual" value={plan?`${plan.kcalTarget} kcal`:'—'} meta={plan?.title||'sem prescrição'} icon={Utensils}/></div><div className="clinicalNote"><span><HeartPulse size={18}/></span><div><b>Objetivo terapêutico</b><p>{data.anamneses[patient.id]?.chiefComplaint||patient.goal}</p></div></div></section><section className="surface"><SectionTitle title="Pendências" description="Itens para revisar no próximo contato"/><div className="taskList"><button onClick={()=>setTab('labs')}><span className="taskIcon amber"><FlaskConical/></span><span><b>{alerts.length} exame(s) fora da faixa registrada</b><small>{alerts.map(x=>x.marker).join(', ')||'Nenhum alerta laboratorial'}</small></span><ChevronRight/></button><button onClick={()=>setTab('goals')}><span className="taskIcon purple"><Target/></span><span><b>{goals.filter(g=>g.progress<80).length} meta(s) abaixo de 80%</b><small>Acompanhar check-ins e barreiras</small></span><ChevronRight/></button><button onClick={()=>setTab('anamnesis')}><span className="taskIcon blue"><ClipboardCheck/></span><span><b>{qs.length} questionário(s) respondido(s)</b><small>Revisar respostas pré-consulta</small></span><ChevronRight/></button></div></section></div><div className="overviewGrid lower"><section className="surface"><SectionTitle title="Evolução recente" description="Peso e medidas em ordem cronológica" action={<Button variant="ghost" onClick={()=>setTab('anthro')}>Ver antropometria</Button>}/><MiniLineChart data={(data.progress[patient.id]||[]).map(x=>({label:x.date,value:x.weight}))}/></section><section className="surface"><SectionTitle title="Plano e metas" description="Aderência ao tratamento"/><div className="goalCompact">{goals.slice(0,4).map(g=><div key={g.id}><div><b>{g.title}</b><span>{g.progress}%</span></div><ProgressBar value={g.progress}/><small>{g.target}</small></div>)}</div></section></div></>
}
function Anamnesis({patient,data,setData}){
  const a=data.anamneses[patient.id]||{}; const update=(key,val)=>setData(d=>({...d,anamneses:{...d.anamneses,[patient.id]:{...(d.anamneses[patient.id]||{}),[key]:val}}})); const fields=[['chiefComplaint','Queixa principal'],['history','Histórico clínico e familiar'],['allergies','Alergias'],['intolerances','Intolerâncias e sensibilidades'],['medications','Medicamentos'],['supplements','Suplementos'],['routine','Rotina e atividade física'],['sleep','Sono'],['bowel','Hábito intestinal'],['hydration','Hidratação'],['alcohol','Álcool'],['smoking','Tabagismo'],['notes','Observações clínicas']]
  return <section className="surface"><SectionTitle title="Anamnese clínica" description="Registro longitudinal e editável. As alterações são persistidas automaticamente no modo demonstração." action={<Badge tone="green"><Check size={13}/> salvo</Badge>}/><div className="anamneseGrid">{fields.map(([key,label])=><Field key={key} label={label}><textarea rows={key==='history'||key==='routine'||key==='notes'?4:2} value={a[key]||''} onChange={e=>update(key,e.target.value)} placeholder="Registrar informação clínica..."/></Field>)}</div></section>
}
function Anthropometry({patient,data,setData}){
  const list=data.anthropometry[patient.id]||[]; const [adding,setAdding]=useState(false); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={id:uid('ant'),date:f.get('date'),weight:Number(f.get('weight')),waist:Number(f.get('waist')),hip:Number(f.get('hip')),arm:Number(f.get('arm')),thigh:Number(f.get('thigh')),bodyFat:Number(f.get('bodyFat')),muscleMass:Number(f.get('muscleMass')),method:f.get('method')};setData(d=>({...d,anthropometry:{...d.anthropometry,[patient.id]:[item,...(d.anthropometry[patient.id]||[])]},patients:d.patients.map(p=>p.id===patient.id?{...p,weight:item.weight}:p)}));setAdding(false)}
  return <section className="surface"><SectionTitle title="Avaliação antropométrica" description="Histórico de composição corporal e perímetros" action={<Button onClick={()=>setAdding(!adding)}><Plus size={16}/> Nova avaliação</Button>}/>{adding&&<form className="inlineForm" onSubmit={submit}><Field label="Data"><input name="date" type="date" defaultValue="2026-08-27" required/></Field><Field label="Peso (kg)"><input name="weight" type="number" step="0.1" defaultValue={patient.weight} required/></Field><Field label="Cintura (cm)"><input name="waist" type="number" step="0.1"/></Field><Field label="Quadril (cm)"><input name="hip" type="number" step="0.1"/></Field><Field label="Braço (cm)"><input name="arm" type="number" step="0.1"/></Field><Field label="Coxa (cm)"><input name="thigh" type="number" step="0.1"/></Field><Field label="Gordura (%)"><input name="bodyFat" type="number" step="0.1"/></Field><Field label="Massa magra (kg)"><input name="muscleMass" type="number" step="0.1"/></Field><Field label="Método"><select name="method"><option>Bioimpedância</option><option>Dobras cutâneas</option><option>Medidas corporais</option></select></Field><div className="inlineActions"><Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Salvar avaliação</Button></div></form>}<div className="assessmentGrid"><div className="assessmentChart"><MiniLineChart data={[...list].reverse().map(x=>({label:x.date,value:x.weight}))} title="Peso (kg)"/></div><div className="assessmentLatest">{list[0]?<><span>Última avaliação</span><strong>{dateBR(list[0].date)}</strong><div className="measureGrid"><div><small>IMC</small><b>{calcBMI(list[0].weight,patient.height)}</b></div><div><small>Gordura</small><b>{list[0].bodyFat||'—'}%</b></div><div><small>Cintura</small><b>{list[0].waist||'—'} cm</b></div><div><small>Massa magra</small><b>{list[0].muscleMass||'—'} kg</b></div></div></>:<Empty/>}</div></div><div className="simpleTable"><div className="simpleHead"><span>Data</span><span>Peso</span><span>Cintura</span><span>Quadril</span><span>% gordura</span><span>Método</span></div>{list.map(x=><div className="simpleRow" key={x.id}><span>{dateBR(x.date)}</span><b>{x.weight} kg</b><span>{x.waist||'—'} cm</span><span>{x.hip||'—'} cm</span><span>{x.bodyFat||'—'}%</span><span>{x.method}</span></div>)}</div></section>
}
function Labs({patient,data,setData}){
  const list=data.labs[patient.id]||[]; const [adding,setAdding]=useState(false); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={id:uid('lab'),date:f.get('date'),marker:f.get('marker'),value:f.get('value'),unit:f.get('unit'),reference:f.get('reference'),status:f.get('status')};setData(d=>({...d,labs:{...d.labs,[patient.id]:[item,...(d.labs[patient.id]||[])]}}));setAdding(false)}
  return <section className="surface"><SectionTitle title="Exames laboratoriais" description="Registro de biomarcadores e faixas de referência informadas pelo profissional" action={<Button onClick={()=>setAdding(!adding)}><Plus size={16}/> Adicionar resultado</Button>}/>{adding&&<form className="inlineForm labsForm" onSubmit={submit}><Field label="Data"><input name="date" type="date" defaultValue="2026-08-27"/></Field><Field label="Marcador"><input name="marker" required/></Field><Field label="Resultado"><input name="value" required/></Field><Field label="Unidade"><input name="unit" placeholder="mg/dL"/></Field><Field label="Referência"><input name="reference" placeholder="70–99"/></Field><Field label="Classificação"><select name="status"><option value="normal">Dentro da faixa</option><option value="attention">Atenção</option></select></Field><div className="inlineActions"><Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Salvar</Button></div></form>}<div className="labSummary"><Stat icon={FlaskConical} label="Resultados" value={list.length} meta="registrados"/><Stat icon={CheckCircle2} label="Dentro da faixa" value={list.filter(x=>x.status==='normal').length} meta="classificação manual"/><Stat icon={HeartPulse} label="Atenção" value={list.filter(x=>x.status==='attention').length} meta="revisar conduta" tone="attention"/></div><div className="simpleTable labs"><div className="simpleHead"><span>Marcador</span><span>Resultado</span><span>Referência</span><span>Data</span><span>Status</span></div>{list.map(x=><div className="simpleRow" key={x.id}><b>{x.marker}</b><strong>{x.value} {x.unit}</strong><span>{x.reference}</span><span>{dateBR(x.date)}</span><Badge tone={x.status==='normal'?'green':'amber'}>{x.status==='normal'?'Dentro da faixa':'Atenção'}</Badge></div>)}</div></section>
}

function MealPlanEditor({patient,data,setData}){
  const plan=data.mealPlans[patient.id]; const [addingMeal,setAddingMeal]=useState(false); const [picker,setPicker]=useState(null); const createPlan=()=>setData(d=>({...d,mealPlans:{...d.mealPlans,[patient.id]:{id:uid('plan'),title:'Novo plano alimentar',status:'active',startDate:'2026-08-27',kcalTarget:2000,macros:{protein:120,carbs:220,fat:65,fiber:30},instructions:'',meals:[]}}})); if(!plan) return <section className="surface"><Empty icon={Utensils} title="Paciente ainda sem plano ativo" text="Crie uma prescrição para iniciar o acompanhamento alimentar."/><div className="centerAction"><Button onClick={createPlan}><Plus size={16}/> Criar plano alimentar</Button></div></section>
  const updatePlan=patch=>setData(d=>({...d,mealPlans:{...d.mealPlans,[patient.id]:{...d.mealPlans[patient.id],...patch}}})); const addMeal=e=>{e.preventDefault();const f=new FormData(e.currentTarget);updatePlan({meals:[...plan.meals,{id:uid('meal'),time:f.get('time'),name:f.get('name'),note:f.get('note'),items:[]}]});setAddingMeal(false)}; const removeItem=(mealId,index)=>updatePlan({meals:plan.meals.map(m=>m.id===mealId?{...m,items:m.items.filter((_,i)=>i!==index)}:m)}); const totals=plan.meals.flatMap(m=>m.items).reduce((a,i)=>({kcal:a.kcal+(i.kcal||0),protein:a.protein+(i.protein||0),carbs:a.carbs+(i.carbs||0),fat:a.fat+(i.fat||0)}),{kcal:0,protein:0,carbs:0,fat:0})
  return <><section className="surface planHeader"><div className="planTitleBlock"><Badge tone="green">Plano ativo</Badge><input className="titleInput" value={plan.title} onChange={e=>updatePlan({title:e.target.value})}/><div className="planMeta"><span>Início {dateBR(plan.startDate)}</span><span>•</span><span>{plan.meals.length} refeições</span><span>•</span><span>{Math.round(totals.kcal)} kcal calculadas</span></div></div><div className="planTargets"><div><small>Energia alvo</small><label><input type="number" value={plan.kcalTarget} onChange={e=>updatePlan({kcalTarget:Number(e.target.value)})}/> kcal</label></div>{[['protein','Proteína','g'],['carbs','Carboidrato','g'],['fat','Gorduras','g'],['fiber','Fibras','g']].map(([key,label,unit])=><div key={key}><small>{label}</small><label><input type="number" value={plan.macros[key]} onChange={e=>updatePlan({macros:{...plan.macros,[key]:Number(e.target.value)}})}/> {unit}</label></div>)}</div></section><section className="surface mealEditor"><SectionTitle title="Prescrição alimentar" description="Monte refeições usando a biblioteca de alimentos. Valores nutricionais são calculados a partir da porção cadastrada." action={<Button variant="secondary" onClick={()=>setAddingMeal(true)}><Plus size={16}/> Nova refeição</Button>}/><Field label="Orientações gerais"><textarea rows="2" value={plan.instructions||''} onChange={e=>updatePlan({instructions:e.target.value})}/></Field>{addingMeal&&<form className="newMealForm" onSubmit={addMeal}><input name="time" type="time" defaultValue="18:00" required/><input name="name" placeholder="Nome da refeição" required/><input name="note" placeholder="Observação opcional"/><Button type="button" variant="ghost" onClick={()=>setAddingMeal(false)}>Cancelar</Button><Button>Adicionar</Button></form>}<div className="mealEditorList">{plan.meals.map((meal,index)=><article className="mealCard" key={meal.id}><div className="mealCardHead"><span className="mealIndex">{String(index+1).padStart(2,'0')}</span><div><strong>{meal.name}</strong><small><Clock3 size={13}/>{meal.time} {meal.note&&`· ${meal.note}`}</small></div><Button variant="ghost" onClick={()=>setPicker(meal.id)}><Plus size={15}/> Alimento</Button></div><div className="foodItems">{meal.items.length?meal.items.map((item,i)=><div className="foodItem" key={`${item.foodId}-${i}`}><span><b>{item.name}</b><small>{item.quantity} {item.unit}</small></span><span>{Math.round(item.kcal)} kcal</span><span>P {item.protein?.toFixed?.(1)||item.protein}g</span><span>C {item.carbs?.toFixed?.(1)||item.carbs}g</span><span>G {item.fat?.toFixed?.(1)||item.fat}g</span><button className="iconBtn subtle" onClick={()=>removeItem(meal.id,i)}><Trash2 size={15}/></button></div>):<div className="emptyMeal">Nenhum alimento nesta refeição.</div>}</div></article>)}</div></section>{picker&&<FoodPicker data={data} mealId={picker} patientId={patient.id} setData={setData} onClose={()=>setPicker(null)}/>}</>
}
function FoodPicker({data,mealId,patientId,setData,onClose}){
  const [query,setQuery]=useState(''); const [qty,setQty]=useState(100); const results=data.foodLibrary.filter(f=>f.name.toLowerCase().includes(query.toLowerCase())).slice(0,8); const add=food=>{const ratio=Number(qty)/food.serving;const item={foodId:food.id,name:food.name,quantity:Number(qty),unit:food.unit,kcal:food.kcal*ratio,protein:food.protein*ratio,carbs:food.carbs*ratio,fat:food.fat*ratio};setData(d=>({...d,mealPlans:{...d.mealPlans,[patientId]:{...d.mealPlans[patientId],meals:d.mealPlans[patientId].meals.map(m=>m.id===mealId?{...m,items:[...m.items,item]}:m)}}}));onClose()}
  return <Modal title="Adicionar alimento" subtitle="Pesquise na biblioteca demonstrativa e ajuste a quantidade." onClose={onClose}><div className="foodPickerTop"><div className="searchBox"><Search size={17}/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar alimento"/></div><Field label="Quantidade"><input type="number" value={qty} onChange={e=>setQty(e.target.value)} min="1"/></Field></div><div className="foodPickerList">{results.map(f=><button key={f.id} onClick={()=>add(f)}><span><b>{f.name}</b><small>{f.group} · porção base {f.serving} {f.unit}</small></span><span><b>{Math.round(f.kcal*(qty/f.serving))} kcal</b><small>P {Math.round(f.protein*(qty/f.serving))} · C {Math.round(f.carbs*(qty/f.serving))} · G {Math.round(f.fat*(qty/f.serving))}</small></span><Plus size={17}/></button>)}</div></Modal>
}
function GoalsModule({patient,data,setData,professional=false}){
  const goals=data.goals[patient.id]||[]; const [adding,setAdding]=useState(false); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const g={id:uid('g'),title:f.get('title'),target:f.get('target'),progress:Number(f.get('progress')||0),frequency:f.get('frequency'),active:true};setData(d=>({...d,goals:{...d.goals,[patient.id]:[...(d.goals[patient.id]||[]),g]}}));setAdding(false)}; const checkIn=id=>setData(d=>({...d,goals:{...d.goals,[patient.id]:(d.goals[patient.id]||[]).map(g=>g.id===id?{...g,progress:Math.min(100,g.progress+10)}:g)}}))
  return <section className="surface"><SectionTitle title={professional?'Metas terapêuticas':'Minhas metas'} description={professional?'Defina comportamentos e acompanhe os check-ins do paciente.':'Registre seu progresso e mantenha o combinado com seu nutricionista.'} action={professional?<Button onClick={()=>setAdding(true)}><Plus size={16}/> Nova meta</Button>:null}/>{adding&&<form className="newGoalForm" onSubmit={submit}><input name="title" placeholder="Ex.: Água" required/><input name="target" placeholder="Ex.: 2,5 L/dia" required/><select name="frequency"><option>Diária</option><option>Semanal</option></select><input name="progress" type="number" min="0" max="100" defaultValue="0"/><Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Adicionar</Button></form>}<div className="goalsGrid">{goals.map(g=><article className="goalCard" key={g.id}><div className="goalIcon"><Target/></div><div className="goalMain"><div><strong>{g.title}</strong><Badge>{g.frequency}</Badge></div><p>{g.target}</p><ProgressBar value={g.progress}/><div className="goalFooter"><span>{g.progress}% concluído</span>{!professional&&<Button variant="ghost" onClick={()=>checkIn(g.id)}><Check size={14}/> Check-in</Button>}</div></div></article>)}</div></section>
}
function DiaryModule({patient,data,setData,professional=false}){
  const entries=data.diary[patient.id]||[]; const [photo,setPhoto]=useState(null); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={id:uid('d'),date:new Date().toISOString(),meal:f.get('meal'),description:f.get('description'),hunger:Number(f.get('hunger')),satiety:Number(f.get('satiety')),mood:f.get('mood'),photo,reaction:null,professionalComment:''};setData(d=>({...d,diary:{...d.diary,[patient.id]:[item,...(d.diary[patient.id]||[])]}}));e.currentTarget.reset();setPhoto(null)}; const handlePhoto=e=>{const file=e.target.files?.[0];if(!file)return;const r=new FileReader();r.onload=()=>setPhoto(r.result);r.readAsDataURL(file)}; const update=(id,patch)=>setData(d=>({...d,diary:{...d.diary,[patient.id]:(d.diary[patient.id]||[]).map(x=>x.id===id?{...x,...patch}:x)}}))
  return <div className="diaryLayout">{!professional&&<section className="surface diaryComposer"><SectionTitle title="Registrar refeição" description="Foto, contexto e percepção ajudam o acompanhamento."/><form onSubmit={submit}><div className="formGrid cols2"><Field label="Refeição"><select name="meal"><option>Café da manhã</option><option>Almoço</option><option>Lanche</option><option>Jantar</option><option>Ceia</option><option>Outro</option></select></Field><Field label="Humor"><select name="mood"><option>Bem</option><option>Neutro</option><option>Cansado</option><option>Ansioso</option><option>Estressado</option></select></Field><Field label="Fome antes (0–10)"><input name="hunger" type="range" min="0" max="10" defaultValue="5"/></Field><Field label="Saciedade depois (0–10)"><input name="satiety" type="range" min="0" max="10" defaultValue="7"/></Field></div><Field label="O que você comeu?"><textarea name="description" required rows="3" placeholder="Descreva a refeição, trocas ou dificuldades..."/></Field><label className="photoUpload"><ImagePlus size={19}/><span>{photo?'Foto anexada':'Adicionar foto'}<small>JPG/PNG · salva localmente nesta demonstração</small></span><input type="file" accept="image/*" onChange={handlePhoto}/></label>{photo&&<img className="diaryPreview" src={photo} alt="Prévia da refeição"/>}<Button type="submit"><Send size={16}/> Registrar no diário</Button></form></section>}<section className="surface"><SectionTitle title={professional?'Diário alimentar do paciente':'Histórico do diário'} description={professional?'Reaja e registre uma orientação para cada refeição.':'Seus registros ficam compartilhados com o nutricionista.'}/><div className="diaryFeed">{entries.length?entries.map(entry=><article className="diaryEntry" key={entry.id}>{entry.photo&&<img src={entry.photo} alt="Refeição registrada"/>}<div className="diaryEntryBody"><div className="entryHead"><div><Badge>{entry.meal}</Badge><strong>{dateBR(entry.date)} · {timeBR(entry.date)}</strong></div><span>Fome {entry.hunger}/10 · Saciedade {entry.satiety}/10</span></div><p>{entry.description}</p><div className="entryMeta"><span>Humor: <b>{entry.mood}</b></span>{entry.reaction&&<Badge tone={entry.reaction==='Ótimo'?'green':'amber'}>{entry.reaction}</Badge>}</div>{professional?<div className="professionalFeedback"><div className="reactionButtons"><button className={entry.reaction==='Ótimo'?'active':''} onClick={()=>update(entry.id,{reaction:'Ótimo'})}>✓ Boa escolha</button><button className={entry.reaction==='Ajustar'?'active warning':''} onClick={()=>update(entry.id,{reaction:'Ajustar'})}>↗ Ajustar</button></div><textarea placeholder="Comentário para o paciente..." value={entry.professionalComment||''} onChange={e=>update(entry.id,{professionalComment:e.target.value})}/></div>:entry.professionalComment&&<div className="nutriComment"><span className="avatar small">MS</span><div><b>Comentário da nutricionista</b><p>{entry.professionalComment}</p></div></div>}</div></article>):<Empty title="Nenhuma refeição registrada" text="Os registros aparecerão aqui."/>}</div></section></div>
}
function DocumentsModule({patient,data,setData,professional=false}){
  const docs=data.documents[patient.id]||[]; const rx=data.prescriptions[patient.id]||[]; const [mode,setMode]=useState('docs'); const [adding,setAdding]=useState(false); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);if(mode==='docs'){const item={id:uid('doc'),title:f.get('title'),type:f.get('type'),date:'2026-08-27',url:f.get('url')||'#'};setData(d=>({...d,documents:{...d.documents,[patient.id]:[item,...(d.documents[patient.id]||[])]}}))}else{const item={id:uid('rx'),title:f.get('title'),formula:f.get('formula'),instructions:f.get('instructions'),date:'2026-08-27'};setData(d=>({...d,prescriptions:{...d.prescriptions,[patient.id]:[item,...(d.prescriptions[patient.id]||[])]}}))}setAdding(false)}
  return <section className="surface"><SectionTitle title={professional?'Documentos e prescrições':'Meus documentos'} description="Materiais compartilhados ao longo do tratamento." action={professional?<Button onClick={()=>setAdding(true)}><Plus size={16}/> Novo</Button>:null}/><div className="subTabs"><button className={mode==='docs'?'active':''} onClick={()=>setMode('docs')}>Documentos</button><button className={mode==='rx'?'active':''} onClick={()=>setMode('rx')}>Prescrições</button></div>{adding&&professional&&<form className="documentForm" onSubmit={submit}>{mode==='docs'?<><Field label="Título"><input name="title" required/></Field><Field label="Tipo"><select name="type"><option>Orientação</option><option>Solicitação</option><option>Atestado</option><option>Material educativo</option></select></Field><Field label="Link do arquivo"><input name="url" placeholder="https://..."/></Field></>:<><Field label="Título"><input name="title" required/></Field><Field label="Fórmula / composição"><textarea name="formula" rows="3" required/></Field><Field label="Modo de uso"><textarea name="instructions" rows="2"/></Field></>}<Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Salvar</Button></form>}{mode==='docs'?<div className="documentList">{docs.map(d=><a href={d.url} key={d.id} onClick={e=>d.url==='#'&&e.preventDefault()}><span className="docIcon"><FileText/></span><span><b>{d.title}</b><small>{d.type} · {dateBR(d.date)}</small></span><Download size={17}/></a>)}</div>:<div className="rxList">{rx.map(r=><article key={r.id}><div><span className="docIcon"><PackagePlus/></span><div><b>{r.title}</b><small>{dateBR(r.date)}</small></div></div><p>{r.formula}</p><span>{r.instructions}</span></article>)}</div>}</section>
}
function RecordModule({patient,data,setData}){
  const notes=data.notes[patient.id]||[]; const [text,setText]=useState(''); const [type,setType]=useState('Evolução'); const add=()=>{if(!text.trim())return;const n={id:uid('n'),date:new Date().toISOString(),author:data.professional.name,type,text:text.trim()};setData(d=>({...d,notes:{...d.notes,[patient.id]:[n,...(d.notes[patient.id]||[])]}}));setText('')}
  return <section className="surface"><SectionTitle title="Prontuário e evolução" description="Registro cronológico de condutas, hipóteses e decisões clínicas."/><div className="recordComposer"><select value={type} onChange={e=>setType(e.target.value)}><option>Evolução</option><option>Consulta</option><option>Intercorrência</option><option>Conduta</option></select><textarea value={text} onChange={e=>setText(e.target.value)} rows="3" placeholder="Registrar evolução clínica..."/><Button onClick={add}><Plus size={16}/> Adicionar registro</Button></div><div className="recordTimeline">{notes.map(n=><article key={n.id}><div className="recordDot"/><div><span>{dateBR(n.date)} · {timeBR(n.date)}</span><h3>{n.type}</h3><p>{n.text}</p><small>{n.author}</small></div></article>)}</div></section>
}

function Agenda({data,setData,onOpenPatient}){
  const [adding,setAdding]=useState(false); const [filter,setFilter]=useState('scheduled'); const rows=data.appointments.filter(a=>filter==='all'||a.status===filter).sort((a,b)=>a.startsAt.localeCompare(b.startsAt)); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={id:uid('a'),patientId:f.get('patientId'),startsAt:`${f.get('date')}T${f.get('time')}`,duration:Number(f.get('duration')),mode:f.get('mode'),type:f.get('type'),status:'scheduled',notes:f.get('notes')};setData(d=>({...d,appointments:[...d.appointments,item],patients:d.patients.map(p=>p.id===item.patientId?{...p,nextAppointment:item.startsAt}:p)}));setAdding(false)}; const setStatus=(id,status)=>setData(d=>({...d,appointments:d.appointments.map(a=>a.id===id?{...a,status}:a)}))
  return <div className="page"><div className="pageIntro"><div><span className="kicker">Consultório</span><h1>Agenda</h1><p>Consultas presenciais e online em uma visão operacional.</p></div><Button onClick={()=>setAdding(true)}><Plus size={17}/> Novo agendamento</Button></div><section className="surface"><div className="agendaToolbar"><div className="subTabs"><button className={filter==='scheduled'?'active':''} onClick={()=>setFilter('scheduled')}>Agendadas</button><button className={filter==='completed'?'active':''} onClick={()=>setFilter('completed')}>Concluídas</button><button className={filter==='all'?'active':''} onClick={()=>setFilter('all')}>Todas</button></div><Button variant="ghost"><CalendarDays size={16}/> Sincronização externa</Button></div><div className="agendaList">{rows.map(a=><article key={a.id}><div className="agendaDate"><b>{new Date(a.startsAt).getDate().toString().padStart(2,'0')}</b><span>{new Date(a.startsAt).toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}</span></div><div className="agendaTime"><Clock3 size={16}/><b>{timeBR(a.startsAt)}</b><span>{a.duration} min</span></div><button className="agendaPatient" onClick={()=>onOpenPatient(a.patientId)}><span className="avatar small">{patientName(data,a.patientId).slice(0,2).toUpperCase()}</span><span><b>{patientName(data,a.patientId)}</b><small>{a.type}</small></span></button><Badge tone={a.mode==='Online'?'blue':'neutral'}>{a.mode}</Badge><div className="agendaActions">{a.status==='scheduled'?<><Button variant="ghost" onClick={()=>setStatus(a.id,'completed')}><Check size={15}/> Concluir</Button><button className="iconBtn"><MoreHorizontal size={18}/></button></>:<Badge tone="green">Concluída</Badge>}</div></article>)}</div></section>{adding&&<Modal title="Novo agendamento" subtitle="Crie um compromisso na agenda clínica." onClose={()=>setAdding(false)}><form onSubmit={submit}><div className="formGrid cols2"><Field label="Paciente"><select name="patientId">{data.patients.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Tipo"><select name="type"><option>Primeira consulta</option><option>Retorno</option><option>Avaliação</option><option>Ajuste de plano</option></select></Field><Field label="Data"><input name="date" type="date" defaultValue="2026-08-28" required/></Field><Field label="Horário"><input name="time" type="time" defaultValue="09:00" required/></Field><Field label="Duração"><select name="duration" defaultValue="45"><option value="30">30 min</option><option value="45">45 min</option><option value="60">60 min</option><option value="90">90 min</option></select></Field><Field label="Modalidade"><select name="mode"><option>Presencial</option><option>Online</option></select></Field></div><Field label="Observações"><textarea name="notes" rows="3"/></Field><div className="modalActions"><Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Agendar consulta</Button></div></form></Modal>}</div>
}
function PlansLibrary({data,setData,onOpenPatient}){
  const [patientId,setPatientId]=useState(data.patients[0]?.id||''); const apply=tpl=>{if(!patientId)return;const current=data.mealPlans[data.patients[0]?.id];const plan=current?{...JSON.parse(JSON.stringify(current)),id:uid('plan'),title:tpl.name,kcalTarget:tpl.kcal,startDate:'2026-08-27'}:{id:uid('plan'),title:tpl.name,status:'active',startDate:'2026-08-27',kcalTarget:tpl.kcal,macros:{protein:120,carbs:220,fat:65,fiber:30},instructions:'Plano criado a partir de um modelo.',meals:[]};setData(d=>({...d,mealPlans:{...d.mealPlans,[patientId]:plan}}));onOpenPatient(patientId)}
  return <div className="page"><div className="pageIntro"><div><span className="kicker">Prescrição</span><h1>Planos e modelos</h1><p>Biblioteca própria para padronizar o trabalho sem engessar a consulta.</p></div><Button><Plus size={17}/> Novo modelo</Button></div><div className="plansLayout"><section className="surface"><SectionTitle title="Modelos do consultório" description="Estruturas reutilizáveis por objetivo ou método"/><div className="templateGrid">{data.planTemplates.map(t=><article key={t.id}><div className="templateIcon"><Utensils/></div><Badge>{t.method}</Badge><h3>{t.name}</h3><div className="templateStats"><span><b>{t.kcal}</b> kcal</span><span><b>{t.meals}</b> refeições</span></div><small>Atualizado em {dateBR(t.updated)}</small><Button variant="secondary" onClick={()=>apply(t)}>Usar modelo</Button></article>)}</div></section><aside className="surface applyPanel"><SectionTitle title="Aplicar a um paciente" description="Selecione o prontuário de destino."/><Field label="Paciente"><select value={patientId} onChange={e=>setPatientId(e.target.value)}>{data.patients.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><div className="tipBox"><Sparkles size={18}/><p>O my nutri mantém o modelo separado do plano individual. Depois de aplicar, você pode personalizar horários, alimentos, macros e orientações sem alterar a biblioteca.</p></div></aside></div></div>
}
function FoodsRecipes({data,setData}){
  const [tab,setTab]=useState('foods'); const [query,setQuery]=useState(''); const [adding,setAdding]=useState(false); const addFood=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={id:uid('f'),name:f.get('name'),group:f.get('group'),serving:Number(f.get('serving')),unit:f.get('unit'),kcal:Number(f.get('kcal')),protein:Number(f.get('protein')),carbs:Number(f.get('carbs')),fat:Number(f.get('fat')),fiber:Number(f.get('fiber')||0),source:'Cadastro próprio'};setData(d=>({...d,foodLibrary:[item,...d.foodLibrary]}));setAdding(false)}; const foods=data.foodLibrary.filter(f=>`${f.name} ${f.group}`.toLowerCase().includes(query.toLowerCase()))
  return <div className="page"><div className="pageIntro"><div><span className="kicker">Base de prescrição</span><h1>Alimentos e receitas</h1><p>Biblioteca independente para cálculo e composição de planos.</p></div><Button onClick={()=>setAdding(true)}><Plus size={17}/> Cadastrar alimento</Button></div><section className="surface"><div className="foodHeader"><div className="subTabs"><button className={tab==='foods'?'active':''} onClick={()=>setTab('foods')}>Alimentos</button><button className={tab==='recipes'?'active':''} onClick={()=>setTab('recipes')}>Receitas</button></div><div className="searchBox"><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar na biblioteca"/></div></div>{tab==='foods'?<div className="simpleTable foodTable"><div className="simpleHead"><span>Alimento</span><span>Porção</span><span>Energia</span><span>Proteína</span><span>Carboidrato</span><span>Gorduras</span><span>Fonte</span></div>{foods.map(f=><div className="simpleRow" key={f.id}><span><b>{f.name}</b><small>{f.group}</small></span><span>{f.serving} {f.unit}</span><b>{f.kcal} kcal</b><span>{f.protein} g</span><span>{f.carbs} g</span><span>{f.fat} g</span><small>{f.source}</small></div>)}</div>:<div className="recipeGrid">{data.recipes.filter(r=>r.name.toLowerCase().includes(query.toLowerCase())).map(r=><article key={r.id}><div className="recipeVisual"><Leaf/></div><Badge>{r.category}</Badge><h3>{r.name}</h3><p>{r.ingredients}</p><div><span>{r.kcal} kcal</span><span>{r.protein} g proteína</span><span>{r.prep}</span></div></article>)}</div>}</section>{adding&&<Modal title="Cadastrar alimento" subtitle="Insira os dados nutricionais da porção de referência." onClose={()=>setAdding(false)}><form onSubmit={addFood}><div className="formGrid cols2"><Field label="Nome"><input name="name" required/></Field><Field label="Grupo"><input name="group" required/></Field><Field label="Porção"><input name="serving" type="number" defaultValue="100" required/></Field><Field label="Unidade"><select name="unit"><option>g</option><option>ml</option><option>unidade</option></select></Field><Field label="Energia (kcal)"><input name="kcal" type="number" required/></Field><Field label="Proteína (g)"><input name="protein" type="number" step="0.1" required/></Field><Field label="Carboidrato (g)"><input name="carbs" type="number" step="0.1" required/></Field><Field label="Gorduras (g)"><input name="fat" type="number" step="0.1" required/></Field><Field label="Fibras (g)"><input name="fiber" type="number" step="0.1"/></Field></div><div className="modalActions"><Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Salvar alimento</Button></div></form></Modal>}</div>
}
function Messages({data,setData,role,patientId:fixedPatient}){
  const [selected,setSelected]=useState(fixedPatient||data.patients[0]?.id); const [text,setText]=useState(''); const patientId=fixedPatient||selected; const thread=data.messages[patientId]||[]; const send=e=>{e.preventDefault();if(!text.trim())return;const msg={id:uid('msg'),from:role==='nutritionist'?'professional':'patient',date:new Date().toISOString(),text:text.trim()};setData(d=>({...d,messages:{...d.messages,[patientId]:[...(d.messages[patientId]||[]),msg]}}));setText('')}
  return <div className={`messagesPage ${fixedPatient?'embedded':''}`}>{!fixedPatient&&<aside className="conversationList"><div className="conversationSearch"><Search size={16}/><input placeholder="Buscar conversa"/></div>{data.patients.map(p=><button key={p.id} className={selected===p.id?'active':''} onClick={()=>setSelected(p.id)}><span className="avatar">{p.name.slice(0,2).toUpperCase()}</span><span><b>{p.name}</b><small>{(data.messages[p.id]||[]).at(-1)?.text||'Sem mensagens'}</small></span></button>)}</aside>}<section className="chatSurface"><header><div className="personCell"><span className="avatar">{patientName(data,patientId).slice(0,2).toUpperCase()}</span><span><b>{patientName(data,patientId)}</b><small>acompanhamento ativo</small></span></div><div><button className="iconBtn"><Search size={18}/></button><button className="iconBtn"><MoreHorizontal size={18}/></button></div></header><div className="chatThread">{thread.map(m=><div key={m.id} className={`bubble ${m.from==='professional'?'professional':'patient'} ${role==='patient'?(m.from==='patient'?'mine':'theirs'):(m.from==='professional'?'mine':'theirs')}`}><p>{m.text}</p><small>{timeBR(m.date)}</small></div>)}</div><form className="chatComposer" onSubmit={send}><button type="button" className="iconBtn"><Plus size={18}/></button><input value={text} onChange={e=>setText(e.target.value)} placeholder="Escreva uma mensagem..."/><Button type="submit"><Send size={16}/></Button></form></section></div>
}
function Finance({data,setData}){
  const [adding,setAdding]=useState(false); const pending=data.finance.filter(x=>x.status==='pending').reduce((a,x)=>a+x.amount,0); const paid=data.finance.filter(x=>x.status==='paid').reduce((a,x)=>a+x.amount,0); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={id:uid('fin'),patientId:f.get('patientId'),description:f.get('description'),dueDate:f.get('dueDate'),amount:Number(f.get('amount')),status:'pending'};setData(d=>({...d,finance:[item,...d.finance]}));setAdding(false)}; const markPaid=id=>setData(d=>({...d,finance:d.finance.map(x=>x.id===id?{...x,status:'paid'}:x)}))
  return <div className="page"><div className="pageIntro"><div><span className="kicker">Gestão do consultório</span><h1>Financeiro</h1><p>Lançamentos simples para acompanhar recebimentos da clínica.</p></div><Button onClick={()=>setAdding(true)}><Plus size={17}/> Novo lançamento</Button></div><section className="statStrip three"><Stat icon={CheckCircle2} label="Recebido" value={money(paid)} meta="lançamentos pagos"/><Stat icon={AlarmClock} label="A receber" value={money(pending)} meta="em aberto"/><Stat icon={Receipt} label="Ticket médio" value={money(data.finance.reduce((a,x)=>a+x.amount,0)/Math.max(data.finance.length,1))} meta="por lançamento"/></section><section className="surface"><SectionTitle title="Lançamentos" description="Histórico financeiro do consultório"/><div className="simpleTable financeTable"><div className="simpleHead"><span>Paciente</span><span>Descrição</span><span>Vencimento</span><span>Valor</span><span>Status</span><span></span></div>{data.finance.map(x=><div className="simpleRow" key={x.id}><b>{patientName(data,x.patientId)}</b><span>{x.description}</span><span>{dateBR(x.dueDate)}</span><strong>{money(x.amount)}</strong><Badge tone={x.status==='paid'?'green':'amber'}>{x.status==='paid'?'Pago':'Em aberto'}</Badge>{x.status==='pending'?<Button variant="ghost" onClick={()=>markPaid(x.id)}><Check size={14}/> Baixar</Button>:<span/>}</div>)}</div></section>{adding&&<Modal title="Novo lançamento" subtitle="Registre uma cobrança ou pagamento previsto." onClose={()=>setAdding(false)}><form onSubmit={submit}><Field label="Paciente"><select name="patientId">{data.patients.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select></Field><Field label="Descrição"><input name="description" required/></Field><div className="formGrid cols2"><Field label="Vencimento"><input name="dueDate" type="date" defaultValue="2026-09-01" required/></Field><Field label="Valor"><input name="amount" type="number" step="0.01" required/></Field></div><div className="modalActions"><Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Salvar lançamento</Button></div></form></Modal>}</div>
}
function Reports({data}){
  const active=data.patients.filter(p=>p.status==='active'); const avg=active.reduce((a,p)=>a+p.adherence,0)/Math.max(active.length,1); const goalGroups=Object.values(data.goals).flat(); const goalAvg=goalGroups.reduce((a,g)=>a+g.progress,0)/Math.max(goalGroups.length,1)
  return <div className="page"><div className="pageIntro"><div><span className="kicker">Inteligência do consultório</span><h1>Relatórios</h1><p>Indicadores agregados para orientar acompanhamento e gestão.</p></div><Button variant="secondary"><Download size={17}/> Exportar resumo</Button></div><section className="statStrip"><Stat icon={UsersRound} label="Ativos" value={active.length} meta="pacientes"/><Stat icon={Target} label="Adesão média" value={`${Math.round(avg)}%`} meta="carteira atual"/><Stat icon={Goal} label="Metas cumpridas" value={`${Math.round(goalAvg)}%`} meta="média dos check-ins"/><Stat icon={CalendarDays} label="Consultas concluídas" value={data.appointments.filter(a=>a.status==='completed').length} meta="período atual"/></section><div className="reportGrid"><section className="surface"><SectionTitle title="Adesão por paciente" description="Comparativo da carteira ativa"/><div className="barChart">{active.map(p=><div key={p.id}><span>{p.name}</span><div><i style={{width:`${p.adherence}%`}}/><b>{p.adherence}%</b></div></div>)}</div></section><section className="surface"><SectionTitle title="Distribuição de objetivos" description="Perfil atual da carteira"/><div className="objectiveList">{Object.entries(active.reduce((acc,p)=>({...acc,[p.goal]:(acc[p.goal]||0)+1}),{})).map(([goal,count])=><div key={goal}><span>{goal}</span><b>{count}</b></div>)}</div></section></div></div>
}
function SettingsPage({data,setData}){
  const s=data.settings; const update=(k,v)=>setData(d=>({...d,settings:{...d.settings,[k]:v}})); return <div className="page"><div className="pageIntro"><div><span className="kicker">Conta e consultório</span><h1>Configurações</h1><p>Identidade, preferências e parâmetros operacionais.</p></div></div><div className="settingsGrid"><section className="surface"><SectionTitle title="Identidade profissional" description="Informações exibidas ao paciente"/><div className="formGrid cols2"><Field label="Nome do consultório"><input value={s.clinicName} onChange={e=>update('clinicName',e.target.value)}/></Field><Field label="CRN"><input value={data.professional.crn} readOnly/></Field><Field label="Cor principal"><div className="colorField"><input type="color" value={s.brandColor} onChange={e=>update('brandColor',e.target.value)}/><input value={s.brandColor} onChange={e=>update('brandColor',e.target.value)}/></div></Field><Field label="Duração padrão"><select value={s.defaultAppointmentDuration} onChange={e=>update('defaultAppointmentDuration',Number(e.target.value))}><option value="30">30 min</option><option value="45">45 min</option><option value="60">60 min</option></select></Field></div></section><section className="surface"><SectionTitle title="Notificações" description="Automatizações internas do acompanhamento"/><label className="switchRow"><span><b>Lembretes de consulta</b><small>Sinalizar consultas próximas no painel.</small></span><input type="checkbox" checked={s.reminders} onChange={e=>update('reminders',e.target.checked)}/></label><label className="switchRow"><span><b>Alertas do diário alimentar</b><small>Destacar novos registros enviados pelo paciente.</small></span><input type="checkbox" checked={s.diaryAlerts} onChange={e=>update('diaryAlerts',e.target.checked)}/></label></section><section className="surface integrationCard"><SectionTitle title="Integrações" description="Conexões externas exigem credenciais próprias em produção."/><div className="integrationRows"><div><span className="integrationIcon"><CalendarDays/></span><span><b>Google Calendar</b><small>Sincronização de agenda</small></span><Badge>configurar</Badge></div><div><span className="integrationIcon"><MessageCircle/></span><span><b>Mensageria</b><small>Canal de atendimento e automações</small></span><Badge>configurar</Badge></div><div><span className="integrationIcon"><ShieldCheck/></span><span><b>Supabase</b><small>Autenticação, banco e storage</small></span><Badge tone="purple">schema pronto</Badge></div></div></section></div></div>
}

function PatientToday({patient,data,setPage}){
  const plan=data.mealPlans[patient.id]; const goals=data.goals[patient.id]||[]; const progress=data.progress[patient.id]||[]; const latest=progress.at(-1); const nextMeal=plan?.meals.find(m=>m.time>=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))||plan?.meals[0]
  return <div className="page patientPage"><div className="patientWelcome"><div><span className="kicker">Quinta-feira · 27 de agosto</span><h1>Bom dia, {firstName(patient.name)}.</h1><p>Seu plano está organizado. Foque no próximo passo.</p></div><Badge tone="green"><CheckCircle2 size={14}/> acompanhamento ativo</Badge></div><div className="patientDashboard"><section className="patientPrimary surface"><div className="nextMeal"><div><span>Próxima refeição</span><strong>{nextMeal?.time||'—'} · {nextMeal?.name||'Plano em atualização'}</strong><p>{nextMeal?.items?.slice(0,3).map(x=>x.name).join(' · ')||'Aguarde a liberação do seu plano.'}</p></div><Button onClick={()=>setPage('myplan')}>Ver plano <ChevronRight size={16}/></Button></div><div className="patientDayStats"><Stat icon={Droplets} label="Hidratação" value={`${latest?.water||0} L`} meta="meta 2,5 L"/><Stat icon={Activity} label="Passos" value={(latest?.steps||0).toLocaleString('pt-BR')} meta="registro mais recente"/><Stat icon={Clock3} label="Sono" value={`${latest?.sleep||0} h`} meta="última noite"/></div></section><section className="surface adherencePanel"><span>Adesão do ciclo</span><div className="bigScore">{patient.adherence}<small>%</small></div><ProgressBar value={patient.adherence}/><p>Consistência acima da meta semanal.</p></section></div><div className="patientDashboard lower"><section className="surface"><SectionTitle title="Metas de hoje" description="Check-ins combinados no acompanhamento" action={<Button variant="ghost" onClick={()=>setPage('goals')}>Ver todas</Button>}/><div className="goalCompact">{goals.slice(0,3).map(g=><div key={g.id}><div><b>{g.title}</b><span>{g.progress}%</span></div><ProgressBar value={g.progress}/><small>{g.target}</small></div>)}</div></section><section className="surface"><SectionTitle title="Próximo contato" description="Sua agenda com a nutricionista"/><div className="nextAppointment"><span className="calendarTile"><b>{patient.nextAppointment?new Date(patient.nextAppointment).getDate():'—'}</b><small>AGO</small></span><div><b>{patient.nextAppointment?dateBR(patient.nextAppointment):'Sem consulta agendada'}</b><p>{patient.nextAppointment?`${timeBR(patient.nextAppointment)} · retorno`:'Entre em contato para agendar.'}</p></div><Button variant="ghost" onClick={()=>setPage('messages')}>Mensagem</Button></div></section></div></div>
}
function PatientPlan({patient,data}){
  const plan=data.mealPlans[patient.id]; if(!plan)return <div className="page"><section className="surface"><Empty icon={Utensils} title="Plano em elaboração" text="Sua nutricionista ainda não liberou um plano alimentar."/></section></div>
  return <div className="page patientPage"><div className="pageIntro"><div><span className="kicker">Prescrição atual</span><h1>{plan.title}</h1><p>{plan.instructions}</p></div><div className="planKcal"><small>Meta energética</small><strong>{plan.kcalTarget} kcal</strong></div></div><section className="macroStrip"><div><span>Proteína</span><b>{plan.macros.protein} g</b></div><div><span>Carboidratos</span><b>{plan.macros.carbs} g</b></div><div><span>Gorduras</span><b>{plan.macros.fat} g</b></div><div><span>Fibras</span><b>{plan.macros.fiber} g</b></div></section><section className="surface patientPlanList">{plan.meals.map((meal,i)=><article key={meal.id}><div className="patientMealTime"><span>{meal.time}</span><i/></div><div className="patientMealCard"><div className="patientMealHead"><div><small>Refeição {String(i+1).padStart(2,'0')}</small><h3>{meal.name}</h3>{meal.note&&<p>{meal.note}</p>}</div><Badge>{Math.round(meal.items.reduce((a,x)=>a+x.kcal,0))} kcal</Badge></div><div className="patientFoodList">{meal.items.map((x,idx)=><div key={idx}><span><b>{x.name}</b><small>{x.quantity} {x.unit}</small></span><span>P {Math.round(x.protein)} · C {Math.round(x.carbs)} · G {Math.round(x.fat)}</span></div>)}</div></div></article>)}</section></div>
}
function ProgressPage({patient,data,setData}){
  const list=data.progress[patient.id]||[]; const [adding,setAdding]=useState(false); const submit=e=>{e.preventDefault();const f=new FormData(e.currentTarget);const item={id:uid('pr'),date:f.get('date'),weight:Number(f.get('weight')),waist:Number(f.get('waist')||0),bodyFat:Number(f.get('bodyFat')||0),water:Number(f.get('water')||0),steps:Number(f.get('steps')||0),sleep:Number(f.get('sleep')||0)};setData(d=>({...d,progress:{...d.progress,[patient.id]:[...(d.progress[patient.id]||[]),item]},patients:d.patients.map(p=>p.id===patient.id?{...p,weight:item.weight}:p)}));setAdding(false)}
  return <div className="page patientPage"><div className="pageIntro"><div><span className="kicker">Acompanhamento</span><h1>Minha evolução</h1><p>Registre medidas e acompanhe a tendência ao longo do ciclo.</p></div><Button onClick={()=>setAdding(true)}><Plus size={17}/> Novo registro</Button></div><div className="progressGrid"><section className="surface"><SectionTitle title="Peso" description="Evolução em kg"/><MiniLineChart data={list.map(x=>({label:x.date,value:x.weight}))} large/></section><section className="surface progressSummary"><span>Desde o início</span><strong className={list.length>1&&list.at(-1).weight<list[0].weight?'positive':''}>{list.length>1?(list.at(-1).weight-list[0].weight).toFixed(1):'0.0'} kg</strong><div><small>Peso atual</small><b>{list.at(-1)?.weight||patient.weight} kg</b></div><div><small>Cintura</small><b>{list.at(-1)?.waist||'—'} cm</b></div><div><small>Gordura</small><b>{list.at(-1)?.bodyFat||'—'}%</b></div></section></div><section className="surface"><div className="simpleTable progressTable"><div className="simpleHead"><span>Data</span><span>Peso</span><span>Cintura</span><span>Gordura</span><span>Água</span><span>Passos</span><span>Sono</span></div>{[...list].reverse().map(x=><div className="simpleRow" key={x.id}><span>{dateBR(x.date)}</span><b>{x.weight} kg</b><span>{x.waist||'—'} cm</span><span>{x.bodyFat||'—'}%</span><span>{x.water||'—'} L</span><span>{(x.steps||0).toLocaleString('pt-BR')}</span><span>{x.sleep||'—'} h</span></div>)}</div></section>{adding&&<Modal title="Registrar evolução" subtitle="Inclua apenas os dados que você mediu hoje." onClose={()=>setAdding(false)}><form onSubmit={submit}><div className="formGrid cols2"><Field label="Data"><input name="date" type="date" defaultValue="2026-08-27" required/></Field><Field label="Peso (kg)"><input name="weight" type="number" step="0.1" defaultValue={patient.weight} required/></Field><Field label="Cintura (cm)"><input name="waist" type="number" step="0.1"/></Field><Field label="Gordura corporal (%)"><input name="bodyFat" type="number" step="0.1"/></Field><Field label="Água (L)"><input name="water" type="number" step="0.1"/></Field><Field label="Passos"><input name="steps" type="number"/></Field><Field label="Sono (h)"><input name="sleep" type="number" step="0.1"/></Field></div><div className="modalActions"><Button type="button" variant="ghost" onClick={()=>setAdding(false)}>Cancelar</Button><Button>Salvar registro</Button></div></form></Modal>}</div>
}
function ProfilePage({patient,data,setData}){
  const update=(key,val)=>setData(d=>({...d,patients:d.patients.map(p=>p.id===patient.id?{...p,[key]:val}:p)})); return <div className="page patientPage"><div className="pageIntro"><div><span className="kicker">Conta</span><h1>Meu perfil</h1><p>Mantenha seus dados de contato atualizados.</p></div></div><div className="settingsGrid"><section className="surface"><SectionTitle title="Dados pessoais" description="Informações compartilhadas com sua nutricionista"/><div className="formGrid cols2"><Field label="Nome"><input value={patient.name} onChange={e=>update('name',e.target.value)}/></Field><Field label="E-mail"><input value={patient.email} onChange={e=>update('email',e.target.value)}/></Field><Field label="Telefone"><input value={patient.phone||''} onChange={e=>update('phone',e.target.value)}/></Field><Field label="Data de nascimento"><input type="date" value={patient.birthDate||''} onChange={e=>update('birthDate',e.target.value)}/></Field></div></section><section className="surface"><SectionTitle title="Privacidade e segurança" description="Controles da conta"/><div className="securityRows"><button><ShieldCheck/><span><b>Alterar senha</b><small>Atualize suas credenciais de acesso</small></span><ChevronRight/></button><button><Bell/><span><b>Notificações</b><small>Preferências de lembretes e mensagens</small></span><ChevronRight/></button></div></section></div></div>
}
function MiniLineChart({data=[],title,large=false}){
  if(!data.length)return <Empty icon={BarChart3} title="Sem dados suficientes" text="Adicione registros para visualizar a evolução."/>; const values=data.map(d=>Number(d.value)||0); const min=Math.min(...values),max=Math.max(...values),range=max-min||1; const points=data.map((d,i)=>`${(i/(Math.max(data.length-1,1)))*100},${82-((d.value-min)/range)*62}`).join(' ')
  return <div className={`miniChart ${large?'large':''}`}>{title&&<span className="chartTitle">{title}</span>}<div className="chartArea"><svg viewBox="0 0 100 90" preserveAspectRatio="none"><line x1="0" x2="100" y1="82" y2="82" className="axis"/><line x1="0" x2="100" y1="51" y2="51" className="gridline"/><line x1="0" x2="100" y1="20" y2="20" className="gridline"/><polyline points={points} fill="none" className="chartLine" vectorEffect="non-scaling-stroke"/>{data.map((d,i)=>{const x=(i/(Math.max(data.length-1,1)))*100;const y=82-((d.value-min)/range)*62;return <circle key={i} cx={x} cy={y} r="1.8" className="chartDot" vectorEffect="non-scaling-stroke"/>})}</svg></div><div className="chartLabels">{data.map((d,i)=><span key={i}>{dateBR(d.label).replace(/ de /g,' ')}</span>)}</div></div>
}

export default function App(){
  const [data,setData]=useState(loadData); const [session,setSession]=useState(()=>{try{return JSON.parse(localStorage.getItem(SESSION_KEY))}catch{return null}}); const [page,setPage]=useState(session?.role==='patient'?'today':'dashboard'); const [selectedPatient,setSelectedPatient]=useState(null); const [addPatient,setAddPatient]=useState(false); const [collapsed,setCollapsed]=useState(false); const [mobileOpen,setMobileOpen]=useState(false)
  useEffect(()=>saveData(data),[data]); useEffect(()=>{if(session)localStorage.setItem(SESSION_KEY,JSON.stringify(session));else localStorage.removeItem(SESSION_KEY)},[session]); if(!session)return <Login onLogin={s=>{setSession(s);setPage(s.role==='patient'?'today':'dashboard')}}/>; const role=session.role; const patient=role==='patient'?(data.patients.find(p=>p.email===session.email)||data.patients[0]):null; const openPatient=id=>{setSelectedPatient(id);setPage('patients')}; let content=null
  if(role==='nutritionist'){
    if(page==='dashboard')content=<Dashboard data={data} setPage={setPage} setSelectedPatient={setSelectedPatient}/>; else if(page==='patients')content=selectedPatient?<PatientWorkspace data={data} setData={setData} patientId={selectedPatient} onBack={()=>setSelectedPatient(null)}/>:<PatientList data={data} onOpen={setSelectedPatient} onAdd={()=>setAddPatient(true)}/>; else if(page==='agenda')content=<Agenda data={data} setData={setData} onOpenPatient={openPatient}/>; else if(page==='plans')content=<PlansLibrary data={data} setData={setData} onOpenPatient={openPatient}/>; else if(page==='foods')content=<FoodsRecipes data={data} setData={setData}/>; else if(page==='messages')content=<div className="page fullHeight"><Messages data={data} setData={setData} role={role}/></div>; else if(page==='finance')content=<Finance data={data} setData={setData}/>; else if(page==='reports')content=<Reports data={data}/>; else content=<SettingsPage data={data} setData={setData}/>
  }else{
    if(page==='today')content=<PatientToday patient={patient} data={data} setPage={setPage}/>; else if(page==='myplan')content=<PatientPlan patient={patient} data={data}/>; else if(page==='diary')content=<div className="page patientPage"><DiaryModule patient={patient} data={data} setData={setData}/></div>; else if(page==='progress')content=<ProgressPage patient={patient} data={data} setData={setData}/>; else if(page==='goals')content=<div className="page patientPage"><GoalsModule patient={patient} data={data} setData={setData}/></div>; else if(page==='messages')content=<div className="page fullHeight patientPage"><Messages data={data} setData={setData} role={role} patientId={patient.id}/></div>; else if(page==='documents')content=<div className="page patientPage"><DocumentsModule patient={patient} data={data} setData={setData}/></div>; else content=<ProfilePage patient={patient} data={data} setData={setData}/>
  }
  return <div className={`appShell ${collapsed?'sideCollapsed':''} ${mobileOpen?'mobileNavOpen':''}`} style={{'--brand':data.settings?.brandColor||'#7151B7'}}><Sidebar role={role} page={page} setPage={p=>{setPage(p);setSelectedPatient(null);setMobileOpen(false)}} logout={()=>setSession(null)} collapsed={collapsed} setCollapsed={setCollapsed}/><div className="workspace"><Topbar role={role} page={page} mobileOpen={mobileOpen} setMobileOpen={setMobileOpen}/><main className="mainContent">{content}</main></div>{mobileOpen&&<button className="mobileScrim" onClick={()=>setMobileOpen(false)}/>} {addPatient&&<AddPatientModal data={data} setData={setData} onClose={()=>setAddPatient(false)} onCreated={id=>{setAddPatient(false);setSelectedPatient(id)}}/>}</div>
}
